{
padding: 0;
margin: 0;
}
{
webkit-box-sizing:border-box;
moz-box-sizing:border-box;
o-box-sizing:border-box;
ms-box-sizing:border-box;
box-sizing:border-box;
}
body{
font-size:14px;
background: #fff;
max-width:1920px;
margin:0 auto;
overflow-x:hidden;
font-family: "Arial",Helvetica,calibri !important;
}
.content{
/*background-image:url(../../assets/images/agri_1.jpg);*/
min-height:700px;
background:#025242;
padding-top:100px;
}
a,a:hover,a:active,a:focus {
display:inline-block;
text-decoration:none;
font-size:14px;
padding:0;
}
h1,h2,h3,h4,h5,h6 {
margin: 0;
/*text-transform: capitalize;*/
}
p {
margin: 0;
font-size:14px;
}
img{ border:none;max-width:100%; height:auto;}
ul{
padding: 0;
margin: 0;
list-style: none;
}
ul li {
list-style: none;
}
select,input,textarea{box-shadow:none;outline:0!important;}
html,body{
height: 100%;
position: relative;
z-index: 2;
}
[placeholder]:focus::-webkit-input-placeholder {
webkit-transition: opacity 0.3s 0.3s ease;
moz-transition: opacity 0.3s 0.3s ease;
ms-transition: opacity 0.3s 0.3s ease;
o-transition: opacity 0.3s 0.3s ease;
transition: opacity 0.3s 0.3s ease;
opacity: 0;
}
/*=============Style css=========*/
/*-------------------------------------
2. Header
-------------------------------------*/
/* .wrapper {
position: relative;
z-index: -1;
} */
.header{
padding-top:20px;
padding-bottom: 12px;
}
.header li  a{
color: #888;
outline: 0;
}
/* header-left  */
.header-left li {
display: inline-block;
margin-right: 50px;
font-size:16px;
font-family: 'Poppins', sans-serif;
webkit-transition: .5s;
moz-transition:.5s;
ms-transition:.5s;
o-transition:.5s;
transition: .5s;
}
.header-left li  i{
margin-right:7px;
color: #888;
}
.header-left li :hover {
color: #7370d8;
}/* header-left  */
/* header-right */
.header-right {
color: #888;
font-family: 'Poppins', sans-serif;
}
.header-right li {
display:inline-block;
}
.header-right li a{
font-size:14px;
font-family: 'Poppins', sans-serif;
padding-bottom: 7px;
webkit-transition: .5s;
moz-transition:.5s;
ms-transition:.5s;
o-transition:.5s;
transition: .5s;
}
.header-right li a:hover{
color:#7370d8;
}
.reg a {
margin-right: 5px;
margin-left: 5px;
}
/* social-icon */
.social-icon{
margin-left:6px;
top:0;
right:0;
}
.social-icon li a {
margin-left:14px;
}/* social-icon */
/* header-right */
/* modal
-------------------*/
.modal-header {
/* border-bottom: none; */
}
.modal-title {
font-size: 30px;
font-weight: 500;
color: #eb1b33;
}
.lg-frm button,
.sm-frm button {
margin-top: 25px;
background: transparent;
border-color: #eb1b33;
color: #eb1b33;
}
/*-------------------------------------
3. Menu
-------------------------------------*/
#menu{
z-index: 999;
padding-top:0px;
}
/* navbar-brand */
.navbar-brand,
.navbar-brand:hover,
.navbar-brand:focus{
margin-top: 33px;
padding:0;
}/* navbar-brand */
/* wrapper-sticky */
.wrapper-sticky{
position: relative;
display: inline-block;
background: #fff;
height:178px !important;
}
/* sticky */
.sticky{
background: #fff;
padding: 10px 0px 0px;
color: #fff;
}
.sticky  .navbar-brand{
margin-top:20px;
}
.sticky  .navbar-default .navbar-nav li a,
.sticky  .navbar-default .navbar-nav li a:active,
.sticky  .navbar-default .navbar-nav li a:focus,
.sticky  .navbar-default .navbar-nav li a:hover{
color: #000;
margin: 0px 0px;
}
.sticky .navbar-default .navbar-toggle ,
.sticky .navbar-default .navbar-toggle:focus,
.sticky .navbar-default .navbar-toggle:hover {
background-color: transparent;
border: 1px solid #000;
margin-top: 4px;
}/* sticky */
/* wrapper-sticky */
/* navbar-default */
.navbar-default {
background-color: transparent;
}
.navbar-default .navbar-nav li a{
font-size: 16px;
color: #000;
margin-top:4px;
padding-bottom: 25px;
padding-left: 25px;
/*-webkit-transition: .5s;
moz-transition:.5s;
ms-transition:.5s;
o-transition:.5s;
transition: .5s;*/
}
.navbar-default .navbar-nav li{
height:38px;
}
.navbar-default.navbar-nav li a:active,
.navbar-default.navbar-nav li a:focus,
.navbar-default .navbar-nav li a:hover{
font-size: 16px;
color: #000;
font-family: 'Lato', sans-serif;
margin-top:4px;
padding-bottom: 25px;
padding-left: 25px;
font-weight:bold;
}
.navbar-default .navbar-nav > .active > a,
.navbar-default .navbar-nav > .active > a:active,
.navbar-default .navbar-nav > .active > a:focus,
.navbar-default .navbar-nav > .active > a:hover {
font-size: 16px;
color: #000;
font-family: 'Lato', sans-serif;
margin-top:7px;
padding-bottom: 25px;
padding-left: 27px;
}/* navbar-default */
/* navbar-toggle*/
.navbar-default .navbar-toggle ,
.navbar-default .navbar-toggle:focus,
.navbar-default .navbar-toggle:hover {
border: 1px solid #000;
margin-top: 25px;
}
.navbar-default .navbar-toggle .icon-bar {
background-color: #000;
}/* navbar-toggle*/
/* .search */
.sticky .search span {
top:16px;
}
.sticky .search input {
top:40px;
}
.search span {
position: absolute;
right: -17px;
top:35px;
cursor: pointer;
z-index: 1;
color: #fff;
}
.search input {
position: absolute;
top:60px;
right: -17px;
width: 15px;
height: 20px;
border-radius: 4px;
font-size: 14px;
padding:20px;
border: 1px solid #ccc;
z-index: 1;
opacity:0;
}
.search input.active{
border-radius: 0 4px;
}/* .search */
/*-------------------------------------
4. Slider
-------------------------------------*/
.header-slider-area {
position: relative;
z-index: 0;
}
/* .single-slide-item */
.single-slide-item {
padding-top: 125px;
padding-bottom:294px;
background-repeat: no-repeat;
background-size: cover;
background-position: center;
}
.single-slide-item h2 {
color:#fff;
font-size:70px;
font-weight:500;
line-height: 1.28;
margin-bottom: 27px;
/*text-transform: capitalize;*/
}
.single-slide-item p {
color:#fefefe;
font-size:24px;
max-width:805px;
line-height: 1.5;
margin-bottom:51px;
}
.single-slide-item button.slide-btn,
.single-slide-item  button:active .slide-btn ,
.single-slide-item button:focus .slide-btn{
display: inline-block;
background: #f5f5fb;
padding: 17px 50px;
color: #5549af;
border: 1px solid #f5f5fb;
font-size:16px;
font-weight:600;
text-transform: uppercase;
font-weight: 700;
margin-right: 36px;
margin-bottom: 30px;
outline:0;
box-shadow:none;
webkit-transition:.5s;
moz-transition:.5s;
ms-transition:.5s;
o-transition:.5s;
transition: .5s;
}
.single-slide-item  button.slide-btn:hover{
background: transparent;
color: #fff;
border: 1px solid #fff;
}
.single-slide-item.slide-1 {
background-image:url(../../assets/images/banner/banner1.jpg);
position:relative;
height:400px;
/*z-index:1;*/
}
.single-slide-item.slide-2 {
background-image:url(../../assets/images/banner/banner2.jpg);
position:relative;
height:400px;
/*z-index:1;*/
}
.single-slide-item.slide-3 {
background-image:url(../../assets/images/banner/banner3.jpg);
position:relative;
height:400px;
/*z-index:1;*/
}
.single-slide-item.slide-1:before,.single-slide-item.slide-2:before,.single-slide-item.slide-3:before{
/*background:rgba(115,112,215,.6);*/
position:absolute;
left:0;
top:0;
width:100%;
height:100%;
content:'';
z-index:-1;
}
.single-slide-item-img img{
width:auto;
/*height:705px;*/
}
/* .single-slide-item */
/* .carousel-indicators */
.carousel-indicators {
bottom: 40px;
display: block;
}
.carousel-indicators li {
display: inline-block;
width: 10px;
height: 10px;
margin: 12px 10px 0 0;
text-indent: -999px;
cursor: pointer;
background-color: #fefefe;
border: 1px solid #fefefe;
border-radius: 10px;
}
.carousel-indicators .active {
width: 12px;
height: 12px;
margin:12px 10px 0 0;
background-color: #f7b405;
border:1px solid #f7b405;
}
/* .carousel-indicators */
/* .carousel-control */
.carousel-control {
position:absolute;
width:75px;
height:75px;
line-height:70px;
text-align:center;
top:40%;
left:20px;
background:#f4f5f9;
color:#fff;
font-size: 22px;
font-weight:700;
font-family: 'Lato', sans-serif;
border-radius: 50%;
webkit-transition:.5s;
moz-transition:.5s;
ms-transition:.5s;
o-transition:.5s;
transition: .5s;
}
.carousel-control:hover {
background: #fff;
color:#6967d1;
font-size: 22px;
}
.carousel-control.left,
.carousel-control.right {
background-image: linear-gradient(to right,rgba(0,0,0,0) 0,rgba(0,0,0,0) 0%);
}
/* .carousel-control */
/* .carousel-fade */
.carousel-fade .carousel-inner .item {
webkit-transition-property: opacity;
transition-property: opacity;
}
.carousel-fade .carousel-inner .item,
.carousel-fade .carousel-inner .active.left,
.carousel-fade .carousel-inner .active.right {
opacity: 0;
}
.carousel-fade .carousel-inner .active,
.carousel-fade .carousel-inner .next.left,
.carousel-fade .carousel-inner .prev.right {
opacity: 1;
}
.carousel-fade .carousel-inner .next,
.carousel-fade .carousel-inner .prev,
.carousel-fade .carousel-inner .active.left,
.carousel-fade .carousel-inner .active.right {
left: 0;
webkit-transform: translate3d(0, 0, 0);
transform: translate3d(0, 0, 0);
}
.carousel-fade .carousel-control {
z-index: 2;
}
