/* project-header  */
/* clear fix */
.isotope:after {
content: '';
display: block;
clear: both;
}
/* ---- .item ---- */
.isotope .col-sm-6 {
width: auto;
}
.isotope .item {
float: left;
height: 286px;
position:relative;
overflow:hidden;
margin-bottom: 30px;
}
.isotope .item.big-height {height: 604px;}
/*.item img*/
.isotope .item img{
width:100%;
height:100%;
transition:.5s;
webkit-transition: .5s;
moz-transition: .5s;
ms-transition: .5s;
o-transition: .5s;
transition: .5s;
}
.isotope .item:hover  img{
webkit-transform:scale(1.5);
moz-transform:scale(1.5);
ms-transform:scale(1.5);
o-transform:scale(1.5);
transform:scale(1.5);
}/*.item img*/
/*.isotope-overlay*/
.isotope-overlay{
position:absolute;
height:100%;
width:100%;
background:rgba(115,112,216,.75);
display:flex;
