height: 800px;
border-radius: 6px;
border-style: solid;
border-color: red;
border-width: 24px 24px 80px;
background-color: black;
}
/* The keyboard of the laptop */
.laptop:after {
content: '';
display: block;
position: absolute;
width: 1600px;
height: 60px;
margin: 80px 0 0 -110px;
background: black;
border-radius: 6px;
}
/* The top of the keyboard */
.laptop:before {
content: '';
display: block;
position: absolute;
width: 250px;
height: 30px;
bottom: -110px;
left: 50%;
webkit-transform: translate(-50%);
transform: translate(-50%);
background: #f1f1f1;
border-bottom-left-radius: 5px;
border-bottom-right-radius: 5px;
z-index: 1;
}
