/* ══════════════════════════════════════════════
LAST DATES GRID (Ultra-Premium / Modern Soft)
══════════════════════════════════════════════ */
.last-dates-grid {
display: grid;
grid-template-columns: repeat(auto-fill, minmax(310px, 1fr));
gap: 22px;
padding: 16px 8px;
}
.ld-card {
background: #ffffff;
/* Extra rounded corners for a modern app feel */
border-radius: 20px;
padding: 28px 24px 24px;
display: flex;
flex-direction: column;
/* Barely visible border, massive ultra-soft shadow */
border: 1px solid rgba(226, 232, 240, 0.4);
box-shadow: 0 10px 40px -10px rgba(15, 23, 42, 0.06), 0 2px 10px -2px rgba(15, 23, 42, 0.02);
transition: transform 0.5s cubic-bezier(0.2, 0.8, 0.2, 1), box-shadow 0.5s ease, border-color 0.5s ease;
position: relative;
overflow: hidden;
z-index: 1;
}
/* Float up and cast a deeper, blue-tinted glow on hover */
.ld-card:hover {
transform: translateY(-8px);
box-shadow: 0 20px 50px -12px rgba(26, 58, 139, 0.15);
border-color: rgba(26, 58, 139, 0.1);
}
/* Sleek top accent line instead of a side border */
.ld-card::before {
content: '';
position: absolute;
top: 0;
left: 0;
right: 0;
height: 4px;
/* Beautiful 3-color gradient */
background: linear-gradient(90deg, #1A3A8B 0%, #3B82F6 50%, #10B981 100%);
opacity: 0.85;
transition: height 0.4s ease, opacity 0.4s ease;
}
.ld-card:hover::before {
height: 6px;
opacity: 1;
}
/* Premium watermark icon in the background (using FontAwesome) */
.ld-card::after {
content: '\f19d'; /* FontAwesome Graduation Cap */
font-family: 'Font Awesome 6 Free';
font-weight: 900;
position: absolute;
bottom: -20px;
right: -20px;
font-size: 130px;
color: rgba(26, 58, 139, 0.025); /* Extremely faint */
transform: rotate(-15deg);
z-index: -1;
transition: all 0.6s cubic-bezier(0.2, 0.8, 0.2, 1);
pointer-events: none;
}
/* Watermark slowly rotates and sharpens on hover */
.ld-card:hover::after {
color: rgba(26, 58, 139, 0.05);
transform: rotate(0deg) scale(1.05);
}
/* Typography Refinements for Premium Look */
.ld-card-main-title {
font-family: var(--ff-head);
font-size: 1.15rem;
font-weight: 800;
color: #0F172A; /* Deep slate, almost black */
margin-bottom: 10px;
letter-spacing: -0.3px;
}
.ld-card-sub {
font-size: 0.88rem;
color: #64748B;
line-height: 1.6;
flex-grow: 1;
margin-bottom: 24px;
}
.ld-card-sub strong {
color: #1E293B;
/*font-weight: 700;*/
}
/* ── Dark Theme Overrides ── */
body[data-theme="dark"] .ld-card {
background: #111827;
border-color: rgba(51, 65, 85, 0.4);
box-shadow: 0 10px 40px -10px rgba(0,0,0,0.5);
}
body[data-theme="dark"] .ld-card:hover {
box-shadow: 0 20px 50px -12px rgba(96, 165, 250, 0.2);
border-color: rgba(96, 165, 250, 0.25);
}
body[data-theme="dark"] .ld-card::after {
color: rgba(255, 255, 255, 0.02);
}
body[data-theme="dark"] .ld-card:hover::after {
color: rgba(255, 255, 255, 0.04);
}
/* ── Premium Soft Pill Badges for Days Left ── */
.ld-days-box {
display: inline-flex;
align-items: center;
padding: 6px 14px;
border-radius: 999px; /* Perfect pill shape */
font-family: var(--ff-head);
font-size: 0.78rem;
font-weight: 800;
letter-spacing: 0.8px;
text-transform: uppercase;
box-shadow: 0 4px 12px -4px rgba(0,0,0,0.05); /* Very soft drop shadow */
transition: transform 0.3s ease, box-shadow 0.3s ease;
}
/* Make the box lift up slightly when you hover over the whole card */
.ld-card:hover .ld-days-box {
transform: translateY(-2px);
box-shadow: 0 8px 16px -4px rgba(0,0,0,0.08);
}
/* Fade the icon slightly to create a premium dual-tone effect */
.ld-days-box i {
opacity: 0.75;
font-size: 0.95rem;
margin-right: 6px;
}
/* Dark Theme Overrides */
body[data-theme="dark"] .ld-days-box {
box-shadow: none;
filter: brightness(0.85) contrast(1.2); /* Adjusts the pastels for dark mode */
}
/* Mobile Adjustments for Grid */
@media (max-width: 768px) {
.last-dates-grid {
grid-template-columns: 1fr;
}
/* --- Custom Cursor --- */
.cursor-dot, .cursor-outline {
position: fixed;
top: 0;
left: 0;
transform: translate(-50%, -50%);
border-radius: 50%;
z-index: 99999;
pointer-events: none; /* Lets you click through it */
}
.cursor-dot {
width: 8px;
height: 8px;
background-color: var(--col-primary); /* Uses your theme color */
}
.cursor-outline {
width: 34px;
height: 34px;
border: 2px solid rgba(26, 58, 139, 0.4);
/* Smooth trailing transition */
transition: left 0.1s ease-out, top 0.1s ease-out, width 0.2s, height 0.2s;
}
/* Enlarge on clickable elements */
a:hover ~ .cursor-outline, button:hover ~ .cursor-outline {
width: 50px;
height: 50px;
background-color: rgba(26, 58, 139, 0.05);
}
/* Hide on mobile/tablets */
@media (max-width: 991px) {
.cursor-dot, .cursor-outline {
display: none !important;
}
/* --- Process Timeline Redesign --- */
.process-block {
background: var(--col-card);
border: 1px solid var(--col-border);
border-radius: var(--r-md);
padding: 24px;
box-shadow: 0 2px 8px rgba(0,0,0,0.03);
}
.process-block.mt-3 {
