align-items: center;
gap: 10px;
}
.process-timeline {
display: flex;
flex-direction: column;
gap: 16px;
position: relative;
padding-left: 24px;
border-left: 2px dashed var(--col-border);
margin-left: 12px;
}
.timeline-step {
display: flex;
align-items: center;
position: relative;
}
.step-number {
width: 32px;
height: 32px;
background: #EBF0FB; /* Light blue */
color: #1A3A8B; /* Primary blue */
border-radius: 50%;
display: flex;
align-items: center;
justify-content: center;
font-weight: 800;
font-size: 0.9rem;
