}
.skeleton-row.long {
width: 95%;
}
.skeleton-row.med {
width: 75%;
}
@keyframes skeletonPulse {
0% {
background-position: 200% 0;
}
100% {
background-position: -200% 0;
}
body[data-theme="dark"] .skeleton-row {
background: linear-gradient(90deg, #1E293B 25%, #334155 50%, #1E293B 75%);
}
