font-weight: 700;
font-size: 0.95rem;
transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.jump-nav-toggle i {
font-size: 1.1rem;
transition: transform 0.3s ease;
}
/* Text hidden by default, slides out on hover */
.jump-nav-toggle span {
max-width: 0;
overflow: hidden;
opacity: 0;
white-space: nowrap;
transition: max-width 0.4s cubic-bezier(0.34, 1.56, 0.64, 1), opacity 0.3s ease;
}
/* The Expandable Menu */
.jump-nav-menu {
display: flex;
flex-direction: column;
background: rgba(255, 255, 255, 0.95);
backdrop-filter: blur(10px);
webkit-backdrop-filter: blur(10px);
border: 1px solid var(--col-border);
border-right: none;
border-radius: 16px 0 0 16px;
padding: 0;
max-height: 0;
overflow: hidden;
opacity: 0;
box-shadow: -4px 10px 25px rgba(0,0,0,0.1);
transition: all 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
}
/* Hover & Active (Click) Expansion States */
.jump-nav:hover .jump-nav-toggle,
.jump-nav.active .jump-nav-toggle {
padding: 14px 20px;
}
.jump-nav:hover .jump-nav-toggle span,
.jump-nav.active .jump-nav-toggle span {
max-width: 200px; /* Expands the button to reveal text */
opacity: 1;
}
.jump-nav:hover .jump-nav-toggle i,
.jump-nav.active .jump-nav-toggle i {
transform: rotate(-90deg); /* Icon points down into the menu */
}
.jump-nav:hover .jump-nav-menu,
.jump-nav.active .jump-nav-menu {
max-height: 500px;
opacity: 1;
padding: 10px 0;
margin-top: 10px;
}
/* Menu Links */
.jump-nav-menu a {
display: flex;
align-items: center;
gap: 14px;
padding: 12px 24px;
color: var(--col-text);
text-decoration: none;
font-size: 0.88rem;
font-weight: 600;
transition: all 0.2s ease;
white-space: nowrap;
}
.jump-nav-menu a i {
color: var(--col-primary);
font-size: 1.1rem;
width: 24px;
text-align: center;
transition: transform 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.jump-nav-menu a:hover {
background: var(--col-bg);
color: var(--col-primary);
padding-left: 28px; /* Slides right slightly on hover */
}
.jump-nav-menu a:hover i {
transform: scale(1.2);
}
/* Dark Theme Support */
body[data-theme="dark"] .jump-nav-menu {
background: rgba(30, 41, 59, 0.95);
border-color: #334155;
}
body[data-theme="dark"] .jump-nav-menu a {
color: #CBD5E1;
}
body[data-theme="dark"] .jump-nav-menu a:hover {
background: #0F172A;
color: #60A5FA;
}
body[data-theme="dark"] .jump-nav-menu a i {
color: #60A5FA;
}
/* ── Dark Theme Overrides for Banner & Notice Board ── */
body[data-theme="dark"] .dept-login-banner,
body[data-theme="dark"] .quick-apply-banner,
body[data-theme="dark"] .notice-card-header {
background: #1E293B;
border-color: #334155;
}
/* ══════════════════════════════════════════════
DISABLE EXTERNAL ARROWS FOR FOOTER LOGOS
══════════════════════════════════════════════ */
.footer-logos-scroll a[target="_blank"]::after {
display: none !important;
content: none !important;
}
/* Remove any relative positioning/padding that might affect the marquee layout */
.footer-logos-scroll a[target="_blank"] {
