/* ══════════════════════════════════════════════
GEN-Z UX ENHANCEMENT LAYER
══════════════════════════════════════════════ */
/* ── Reusable CSS utility animation classes ──
Drop any of these onto a future element's class list. */
.anim-fade-up {
animation: gzFadeUp .5s var(--ease) both;
}
.anim-pop {
animation: gzPopIn .4s cubic-bezier(.34,1.56,.64,1) both;
}
.press-scale {
transition: transform .15s var(--ease);
}
.press-scale:active {
transform: scale(.94);
}
.hover-lift {
transition: transform .25s var(--ease), box-shadow .25s var(--ease);
}
.hover-lift:hover {
transform: translateY(-4px);
box-shadow: var(--sh-md);
}
@keyframes gzFadeUp {
from {
opacity: 0;
transform: translateY(16px);
}
to {
opacity: 1;
transform: translateY(0);
}
@keyframes gzPopIn {
from {
opacity: 0;
transform: scale(.85);
}
to {
opacity: 1;
transform: scale(1);
}
/* ── Magnetic CTA Buttons (qab-btn = your quick-apply "Create Account" /
"Student Login" pills). JS in Main.Master drives the pull + the
cursor-tracked glow via --mx/--my. Desktop/mouse only — see §2c. ── */
.qab-btn {
will-change: transform;
}
.qab-btn-primary::after {
content: '';
position: absolute;
inset: 0;
border-radius: inherit;
background: radial-gradient(circle at var(--mx, 50%) var(--my, 50%), rgba(139,26,26,.18), transparent 60%);
opacity: 0;
transition: opacity .3s ease;
z-index: -1;
pointer-events: none;
}
.qab-btn-primary:hover::after {
opacity: 1;
}
/* ── Liquid Tab Transition — adds a squash/stretch overshoot to the
sliding pill you already have (.tab-nav-bar::after) while it travels
between tabs. JS toggles .liquid-squish on tab change — see §2d. ── */
@keyframes liquidSquish {
0% {
transform: scaleX(1);
}
35% {
transform: scaleX(1.14);
}
65% {
transform: scaleX(0.94);
}
100% {
transform: scaleX(1);
}
.tab-nav-bar.liquid-squish::after {
animation: liquidSquish .42s var(--ease) both;
transform-origin: center;
}
/* ── Staggered Card Entrances — extends the existing corner-card
cascade pattern (reuses your ccEntry keyframe) to the helpline grid,
which currently has no stagger. No markup/C# change needed — each
.helpline-card already ships with its own .reveal class from
BuildHelplineHtml(). ── */
.helpline-grid .helpline-card.reveal.visible {
animation: ccEntry .5s cubic-bezier(.34,1.1,.64,1) both;
}
.helpline-grid .helpline-card:nth-child(1).reveal.visible {
animation-delay: .04s;
}
.helpline-grid .helpline-card:nth-child(2).reveal.visible {
animation-delay: .10s;
}
.helpline-grid .helpline-card:nth-child(3).reveal.visible {
animation-delay: .16s;
}
.helpline-grid .helpline-card:nth-child(4).reveal.visible {
animation-delay: .22s;
}
.helpline-grid .helpline-card:nth-child(5).reveal.visible {
animation-delay: .28s;
}
.helpline-grid .helpline-card:nth-child(6).reveal.visible {
animation-delay: .34s;
}
.helpline-grid .helpline-card:nth-child(7).reveal.visible {
animation-delay: .40s;
}
/* ── High Thumb Usability — bumps small circular icon buttons up to
the 44×44px minimum touch target on real touch devices only (mouse
users on desktop keep the current compact sizing). ── */
@media (hover: none) and (pointer: coarse) {
.theme-toggle-btn,
.elig-modal-close,
.jump-nav-toggle,
.ticker-ctrl-btn {
min-width: 44px;
min-height: 44px;
}
.font-ctrl-btn {
min-height: 40px;
padding: 8px 12px;
}
.qab-btn,
.tab-btn,
.pp-btn {
min-height: 44px;
}
/* ── No Layout Overlapping — the expanded Jump-to-Contents menu
(.jump-nav.active) can grow tall enough on short mobile viewports to
sit visually on top of the fixed Scroll-to-Top button. JS toggles
body.jump-nav-open — see §2e — so we hide the FAB while the menu is
open instead of letting them collide. ── */
body.jump-nav-open .scroll-to-top-wrap {
opacity: 0;
visibility: hidden;
pointer-events: none;
}
/* ── Smooth Fluid Performance — respect reduced-motion users, and cap
animation cost across the new + existing motion in this file. ── */
@media (prefers-reduced-motion: reduce) {
, *::before, *::after {
animation-duration: .001ms !important;
animation-iteration-count: 1 !important;
transition-duration: .001ms !important;
scroll-behavior: auto !important;
}
.ticker-inner, .footer-logos-scroll {
animation: none !important;
}
/* Make stats cards show a pointer finger when hovered */
.custom-scroll-link {
cursor: pointer;
}
/* ══════════════════════════════════════════════════════
NEW RESPONSIVE HEADER LAYOUT (3-COLUMN)
══════════════════════════════════════════════════════ */
.new-header-layout {
display: flex;
align-items: center;
justify-content: space-between;
gap: 15px;
width: 100%;
}
/* Left: CM Block */
.header-left-cm {
flex: 1;
display: flex;
justify-content: flex-start;
min-width: 0; /* Allows shrinking on smaller screens */
}
.header-left-cm img {
height: 100px;
max-width: 100%;
border-radius: 8px;
/* FIX: Changed from cover to contain so text inside the image isn't cropped! */
object-fit: contain;
}
/* Center: GOK Emblem + Text */
.header-center-gok {
display: flex;
align-items: center;
justify-content: center;
gap: 14px;
flex: 2; /* Give center more priority on desktop */
min-width: 0;
}
.header-center-gok .header-portal-name {
text-align: left;
}
.header-center-gok .gov-name {
font-size: 1.15rem;
font-weight: 800;
color: var(--col-head);
line-height: 1.3;
}
.header-center-gok .ssp-name {
font-size: 0.95rem;
font-weight: 700;
color: var(--col-primary);
display: block;
}
/* Right: PKIT Logo */
.header-right-logo {
flex: 1;
display: flex;
justify-content: flex-end;
min-width: 0;
}
.header-right-logo img {
height: 95px;
max-width: 100%;
object-fit: contain;
}
/* --- TABLET Adjustments --- */
@media (max-width: 1100px) {
.header-left-cm img {
height: 80px;
}
.header-right-logo img {
height: 75px;
}
.header-center-gok .gov-name {
font-size: 1rem;
}
.header-center-gok .ssp-name {
font-size: 0.85rem;
}
/* --- MOBILE Adjustments (Perfect Stacking) --- */
@media (max-width: 768px) {
.new-header-layout {
flex-wrap: wrap; /* Critical rule for stacking */
padding: 8px 0;
gap: 12px;
}
/* Force Center block to top, full width */
.header-center-gok {
order: 1;
flex: 0 0 100%;
flex-direction: row;
justify-content: center;
}
/* CM Left & PKIT Right take exactly 48% each on the 2nd row */
.header-left-cm {
order: 2;
flex: 0 0 48%;
justify-content: flex-start;
}
.header-right-logo {
order: 3;
flex: 0 0 48%;
justify-content: flex-end;
}
/* Scale down images safely without clipping */
.header-gok-emblem img {
height: 50px;
}
/* Force images to scale proportionally inside their 48% columns */
.header-left-cm img {
height: auto;
max-height: 60px;
width: 100%;
object-fit: contain;
object-position: left center; /* Hugs the left edge */
}
.header-right-logo img {
height: auto;
max-height: 60px;
width: 100%;
object-fit: contain;
object-position: right center; /* Hugs the right edge */
}
.header-center-gok .gov-name {
font-size: 0.95rem;
}
.header-center-gok .ssp-name {
font-size: 0.8rem;
}
/* --- TINY MOBILE Phones & FOLDABLES --- */
@media (max-width: 420px) {
.header-gok-emblem img {
height: 40px;
}
.header-left-cm img {
max-height: 48px;
}
.header-right-logo img {
max-height: 48px;
}
.header-center-gok .gov-name {
font-size: 0.85rem;
}
.header-center-gok .ssp-name {
font-size: 0.75rem;
}
