transition: transform 0.25s cubic-bezier(0.16, 1, 0.3, 1), color 0.25s cubic-bezier(0.16, 1, 0.3, 1);
will-change: transform, color;
}
/* Float State: When focused OR when text is entered (placeholder is NOT shown) */
.search-input:focus ~ .search-label,
.search-input:not(:placeholder-shown) ~ .search-label {
transform: translateY(-135%) scale(0.85);
color: #007bff;
font-weight: 600;
}
