/* ══════════════════════════════════════════════════════
WCAG 1.4.4 & GIGW 3.0 5.2.15 FIX (200% Zoom Compliance)
══════════════════════════════════════════════════════ */
/* 1. Global Fix: Prevent horizontal scrolling on all pages at 200% zoom */
html, body {
max-width: 100vw;
overflow-x: hidden !important;
}
/* Force long words, URLs, and rigid strings to wrap instead of pushing screen wider */
p, a, span, td, th, li, div, h1, h2, h3, h4, h5, h6 {
overflow-wrap: break-word !important;
word-wrap: break-word !important;
}
/* Ensure data tables on pages like RTI don't break the layout */
table {
max-width: 100%;
overflow-x: auto;
display: block; /* Allows table to scroll internally if too wide, saving the page */
}
/* 2. Specific Fix: Stop text clipping in the Portal Stats Bar */
.stat-item {
height: auto !important; /* Allows card to grow taller if text wraps */
min-height: 100%;
display: flex;
flex-direction: column;
justify-content: center;
}
.stat-number {
white-space: normal !important; /* Overrides any nowrap commands */
word-break: break-word;
}
.stat-label {
white-space: normal !important; /* Allows long labels to wrap to 2 or 3 lines */
word-break: break-word;
line-height: 1.4; /* Gives breathing room to wrapped text */
}
.stat-label .lbl {
white-space: normal !important;
}

