.message {
background: #a07d06e0;
color:#FFF;
position: absolute;
top: -250px;
right: 0;
width: 48%;
transition: top 300ms cubic-bezier(0.17, 0.04, 0.03, 0.94);
overflow: hidden;
box-sizing: border-box;
z-index: 9999;
}
.message h1 {
color:#FFF;
}
#toggle {
position:absolute;
appearance:none;
cursor:pointer;
left:-100%;
top:-100%;
}
#toggle + label {
position: absolute;
right: 0;
/* float: left; */
cursor: pointer;
padding: 10px;
background: #9e7b03;
width: auto;
/* border-radius: 3px; */
padding: 14px 8px;
color: #FFF;
line-height: 10px;
font-size: 12px;
text-align: center;
webkit-font-smoothing: antialiased;
cursor: pointer;
/* margin: 20px 50px; */
transition: all 500ms ease;
z-index: 99999;
}
#toggle + label:after {
content:"Open Accessibility Controls"
}
.container {
transition: margin 300ms cubic-bezier(0.17, 0.04, 0.03, 0.94);
}
#toggle:checked ~ .message {
top: 0;
}
#toggle:checked ~ .container {
margin-top: 250px;
}
#toggle:checked + label {
background:#dd6149;
}
#toggle:checked + label:after {
content:"Close"
}
